pub noinline fn getSSLException(globalThis: *jsc.JSGlobalObject, defaultMessage: []const u8) JSValue {
        var zig_str: ZigString = ZigString.init("");
        _ = &zig_str;
        var output_buf: [4096]u8 = undefined;
        _ = &output_buf;
        output_buf[cp_cast_int(usize, 0)] = 0;
        var written: usize = 0;
        _ = &written;
        var ssl_error = BoringSSL.ERR_get_error;
        _ = &ssl_error;
        while (((ssl_error != 0) and (written < output_buf.len))) : (ssl_error = BoringSSL.ERR_get_error) {
            if ((written > 0)) {
                output_buf[cp_cast_int(usize, written)] = 10;
                written = (written + 1);
            }
            if (BoringSSL.ERR_reason_error_string(ssl_error)) |reason_ptr| {
                _ = &reason_ptr;
                const reason = std.mem.span(reason_ptr);
                if ((reason.len == 0)) {
                    break;
                }
                _ = @memcpy(output_buf[written..][0..reason.len], reason);
                written = (written + reason.len);
            }
            if (BoringSSL.ERR_func_error_string(ssl_error)) |reason_ptr| {
                _ = &reason_ptr;
                const reason = std.mem.span(reason_ptr);
                if ((reason.len > 0)) {
                    _ = @memcpy(output_buf[written..][0.." via ".len], " via ");
                    written = (written + " via ".len);
                    _ = @memcpy(output_buf[written..][0..reason.len], reason);
                    written = (written + reason.len);
                }
            }
            if (BoringSSL.ERR_lib_error_string(ssl_error)) |reason_ptr| {
                _ = &reason_ptr;
                const reason = std.mem.span(reason_ptr);
                if ((reason.len > 0)) {
                    output_buf[written..][cp_cast_int(usize, 0)] = 32;
                    written = (written + 1);
                    _ = @memcpy(output_buf[written..][0..reason.len], reason);
                    written = (written + reason.len);
                }
            }
        }
        if ((written > 0)) {
            const message = output_buf[0..written];
            zig_str = ZigString.init(bun.handleOom(std.fmt.allocPrint(bun.default_allocator, "OpenSSL {s}", .{ message })));
            var encoded_str = zig_str.withEncoding();
            _ = &encoded_str;
            _ = encoded_str.markGlobal();
            _ = BoringSSL.ERR_clear_error;
        }
        if ((zig_str.len == 0)) {
            zig_str = ZigString.init(defaultMessage);
        }
        const exception = zig_str.toErrorInstance(globalThis);
        _ = exception.ensureStillAlive();
        return exception;
}
